  618: ["阐明／揭示。", "有助于解释某种情况。", "“希望这份报告能帮我们弄清这个问题。”"],
  619: ["铺平道路。", "为某事的发生创造便利。", "“这项协议为未来的合作铺平了道路。”"],
  620: ["各种各样的。", "许多不同的种类。", "“我们提供各种各样的产品。”"],
  621: ["万一……（发生）。", "如果某事发生。", "“万一发生紧急情况，请拨打 911。”"],
  622: ["在……之前。", "在……之前（正式）。", "“请在会议开始前十分钟到达。”"],
  623: ["在……之后。", "在……之后（正式）。", "“会议之后，我们发了一封邮件。”"],
  624: ["尽管。", "尽管（很正式）。", "“尽管存在种种问题，项目还是成功了。”"],
